class Solution {
public:
    int longestMountain(vector<int>& arr) {
        int n = arr.size(), best = 0, start = 0;
        while (start < n) {
            int end = start;
            if (end + 1 < n && arr[end] < arr[end + 1]) {
                while (end + 1 < n && arr[end] < arr[end + 1]) end++;
                if (end + 1 < n && arr[end] > arr[end + 1]) {
                    while (end + 1 < n && arr[end] > arr[end + 1]) end++;
                    best = max(best, end - start + 1);
                }
            }
            start = max(end, start + 1);
        }
        return best;
    }
};
